//! `linalg` generated by `mlirformat tblgen` (`linalg.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "linalg.gen.rs"]
mod linalg;

#[test]
fn linalg_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<linalg::Linalg>();
    common::Fixtures::check_dialect(&opt, "linalg");
}
